// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

static void zero_len_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "xyz", 0));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "xyz", 0));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "", 0));
}

static void equal_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "hello", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "hello", 100));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "", 1));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "", 10));
}

static void case_insensitive_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("HELLO", "hello", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "HELLO", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("HeLLo WoRLd", "hEllO wOrlD", 11));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("a", "A", 1));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("z", "Z", 1));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcdefghijklmnopqrstuvwxyz",
					     "ABCDEFGHIJKLMNOPQRSTUVWXYZ", 26));
}

static void length_limit_test(struct kunit *test)
{
	/* Difference lies beyond len */
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcX", "abcY", 3));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcdef", "ABCxyz", 3));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "abd", 2));
	/* Difference exactly at the last compared char */
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "abcY", 4), 0);
	/* Difference at the first char with len 1 */
	KUNIT_EXPECT_LT(test, strncasecmp("a", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("b", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("ab", "ac", 1));
}

static void ordering_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("banana", "apple", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("APPLE", "banana", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("BANANA", "apple", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ABD", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABD", "abc", 3), 0);
}

static void return_value_test(struct kunit *test)
{
	/* Result is the difference of the lowercased characters */
	KUNIT_EXPECT_EQ(test, -2, strncasecmp("a", "c", 1));
	KUNIT_EXPECT_EQ(test, -2, strncasecmp("A", "c", 1));
	KUNIT_EXPECT_EQ(test, -2, strncasecmp("a", "C", 1));
	KUNIT_EXPECT_EQ(test, 2, strncasecmp("C", "a", 1));
	KUNIT_EXPECT_EQ(test, 1, strncasecmp("B", "a", 1));
	KUNIT_EXPECT_EQ(test, -1, strncasecmp("abc", "abd", 3));
}

static void different_length_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "abc", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 100), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABCD", "abc", 100), 0);
	/* Shorter string fully compared equal when len covers only it */
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "ABCD", 3));
	KUNIT_EXPECT_EQ(test, -'d', strncasecmp("abc", "abcd", 4));
	KUNIT_EXPECT_EQ(test, 'd', strncasecmp("abcd", "abc", 4));
}

static void empty_string_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "abc", 10), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abc", "", 10), 0);
}

static void nul_terminator_test(struct kunit *test)
{
	/* Data after the NUL must never be compared */
	static const char a[] = { 'a', 'b', '\0', 'x', 'y' };
	static const char b[] = { 'A', 'B', '\0', 'p', 'q' };

	KUNIT_EXPECT_EQ(test, 0, strncasecmp(a, b, 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp(a, b, 3));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp(a, b, 2));
}

static void non_letter_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("123-_.", "123-_.", 6));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("1", "2", 1));
	/* '@' (0x40) and '[' (0x5b) bracket the uppercase range; not letters */
	KUNIT_EXPECT_NE(test, 0, strncasecmp("@", "`", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("[", "{", 1));
	KUNIT_EXPECT_LT(test, strncasecmp("@", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, '[' - 'a', strncasecmp("[", "a", 1));
	KUNIT_EXPECT_EQ(test, '`' - 'a', strncasecmp("`", "A", 1));
	KUNIT_EXPECT_EQ(test, '_' - 'a', strncasecmp("_", "A", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("a b", "a_b", 3));
}

static void high_byte_test(struct kunit *test)
{
	/* Characters are compared as unsigned char */
	KUNIT_EXPECT_GT(test, strncasecmp("\xff", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "\xff", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("\xe9", "\xe9", 1));
	KUNIT_EXPECT_EQ(test, 0xff - 'z', strncasecmp("\xff", "Z", 1));
}

static void first_difference_wins_test(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("aBz", "abA", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("xa", "yz", 2), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ya", "xz", 2), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcdefgh", "abcdefgi", 8), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcdefgh", "ABCDEFGI", 7));
}

static void symmetry_test(struct kunit *test)
{
	static const char * const strs[] = { "", "a", "A", "abc", "ABD", "b", "Zeta" };
	int i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(strs); j++) {
			int r1 = strncasecmp(strs[i], strs[j], 4);
			int r2 = strncasecmp(strs[j], strs[i], 4);

			KUNIT_EXPECT_EQ(test, r1, -r2);
		}
	}
}

static void large_len_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "ABC", (size_t)-1));
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", (size_t)-1), 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(zero_len_test),
	KUNIT_CASE(equal_test),
	KUNIT_CASE(case_insensitive_test),
	KUNIT_CASE(length_limit_test),
	KUNIT_CASE(ordering_test),
	KUNIT_CASE(return_value_test),
	KUNIT_CASE(different_length_test),
	KUNIT_CASE(empty_string_test),
	KUNIT_CASE(nul_terminator_test),
	KUNIT_CASE(non_letter_test),
	KUNIT_CASE(high_byte_test),
	KUNIT_CASE(first_difference_wins_test),
	KUNIT_CASE(symmetry_test),
	KUNIT_CASE(large_len_test),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strncasecmp");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/module.h>
#include <linux/slab.h>
#include <linux/string.h>

static void cspn_empty_s(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
}

static void cspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", ""), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
}

static void cspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "HELLO"), (size_t)5);
}

static void cspn_match_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "h"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyzh"), (size_t)0);
}

static void cspn_match_last(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "o"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("ab", "b"), (size_t)1);
}

static void cspn_match_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello world", " "), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "de"), (size_t)3);
}

static void cspn_first_of_multiple(struct kunit *test)
{
	/* earliest position in s wins, regardless of order in reject */
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fdb"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("aabbcc", "c"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("abab", "b"), (size_t)1);
}

static void cspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "C"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), (size_t)3);
}

static void cspn_reject_last_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("xyz", "abz"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("xyz", "zab"), (size_t)2);
}

static void cspn_nul_not_matched(struct kunit *test)
{
	/* the terminator is not part of the reject set; result is strlen */
	KUNIT_EXPECT_EQ(test, strcspn("abc", "xyz"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abc\0def", "d"), (size_t)3);
}

static void cspn_repeated_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcd", "cccc"), (size_t)2);
}

static void cspn_all_rejected(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "cba"), (size_t)0);
}

static void cspn_high_bit_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80\xff" "c", "\xff"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80\xff" "c", "\x80"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80" "c", "\x01"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("a\x7f" "b", "\x7f"), (size_t)1);
}

static void cspn_long_string(struct kunit *test)
{
	char *buf = kunit_kzalloc(test, 4097, GFP_KERNEL);
	size_t i;

	KUNIT_ASSERT_NOT_NULL(test, buf);
	for (i = 0; i < 4096; i++)
		buf[i] = 'a';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)4096);
	buf[4095] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)4095);
	buf[2048] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)2048);
}

static void cspn_special_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "=:"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("line\n", "\n"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("a\tb", " \t"), (size_t)1);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(cspn_empty_s),
	KUNIT_CASE(cspn_empty_reject),
	KUNIT_CASE(cspn_no_match),
	KUNIT_CASE(cspn_match_first),
	KUNIT_CASE(cspn_match_last),
	KUNIT_CASE(cspn_match_middle),
	KUNIT_CASE(cspn_first_of_multiple),
	KUNIT_CASE(cspn_case_sensitive),
	KUNIT_CASE(cspn_reject_last_char),
	KUNIT_CASE(cspn_nul_not_matched),
	KUNIT_CASE(cspn_repeated_reject),
	KUNIT_CASE(cspn_all_rejected),
	KUNIT_CASE(cspn_high_bit_chars),
	KUNIT_CASE(cspn_long_string),
	KUNIT_CASE(cspn_special_chars),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strcspn");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>
#include <linux/limits.h>

static void check(struct kunit *test, u64 size, u64 blk, unsigned int units,
		  const char *expect)
{
	char buf[32];
	int ret;

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(size, blk, units, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, expect);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(expect));
}

static void zero_cases(struct kunit *test)
{
	check(test, 0, 1, STRING_UNITS_10, "0 B");
	check(test, 0, 1, STRING_UNITS_2, "0 B");
	check(test, 0, 512, STRING_UNITS_10, "0 B");
	check(test, 1, 0, STRING_UNITS_10, "0 B");
	check(test, 1000, 0, STRING_UNITS_2, "0 B");
	check(test, 0, 0, STRING_UNITS_10, "0 B");
	check(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B");
	check(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "0 ");
}

static void below_divisor(struct kunit *test)
{
	check(test, 1, 1, STRING_UNITS_10, "1 B");
	check(test, 999, 1, STRING_UNITS_10, "999 B");
	check(test, 1023, 1, STRING_UNITS_2, "1023 B");
	/* 1000 is below 1024 in base 2 */
	check(test, 1000, 1, STRING_UNITS_2, "1000 B");
}

static void divisor_boundary(struct kunit *test)
{
	check(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	check(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	check(test, 1024, 1, STRING_UNITS_10, "1.02 kB");
	check(test, 1000000, 1, STRING_UNITS_10, "1.00 MB");
	check(test, 1048576, 1, STRING_UNITS_2, "1.00 MiB");
	check(test, 1000000000, 1, STRING_UNITS_10, "1.00 GB");
	check(test, 1ULL << 30, 1, STRING_UNITS_2, "1.00 GiB");
	check(test, 1ULL << 40, 1, STRING_UNITS_2, "1.00 TiB");
	check(test, 1000000000000ULL, 1, STRING_UNITS_10, "1.00 TB");
	check(test, 1ULL << 50, 1, STRING_UNITS_2, "1.00 PiB");
	check(test, 1ULL << 60, 1, STRING_UNITS_2, "1.00 EiB");
}

static void rounding_base10(struct kunit *test)
{
	check(test, 1004, 1, STRING_UNITS_10, "1.00 kB");
	check(test, 1005, 1, STRING_UNITS_10, "1.01 kB");
	check(test, 1994, 1, STRING_UNITS_10, "1.99 kB");
	check(test, 1995, 1, STRING_UNITS_10, "2.00 kB");
	check(test, 1999, 1, STRING_UNITS_10, "2.00 kB");
	check(test, 9994, 1, STRING_UNITS_10, "9.99 kB");
	check(test, 9995, 1, STRING_UNITS_10, "10.00 kB");
}

static void significant_figures(struct kunit *test)
{
	check(test, 10000, 1, STRING_UNITS_10, "10.0 kB");
	check(test, 12345, 1, STRING_UNITS_10, "12.3 kB");
	check(test, 99949, 1, STRING_UNITS_10, "99.9 kB");
	check(test, 99950, 1, STRING_UNITS_10, "100.0 kB");
	check(test, 100000, 1, STRING_UNITS_10, "100 kB");
	check(test, 999499, 1, STRING_UNITS_10, "999 kB");
	check(test, 999500, 1, STRING_UNITS_10, "1000 kB");
}

static void base2_fractions(struct kunit *test)
{
	check(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	check(test, 1280, 1, STRING_UNITS_2, "1.25 KiB");
	check(test, 2048, 1, STRING_UNITS_2, "2.00 KiB");
	check(test, 10240, 1, STRING_UNITS_2, "10.0 KiB");
	check(test, 102400, 1, STRING_UNITS_2, "100 KiB");
}

static void block_size(struct kunit *test)
{
	check(test, 2, 512, STRING_UNITS_10, "1.02 kB");
	check(test, 2, 512, STRING_UNITS_2, "1.00 KiB");
	check(test, 1, 4096, STRING_UNITS_2, "4.00 KiB");
	check(test, 2048, 512, STRING_UNITS_2, "1.00 MiB");
	check(test, 1000, 1000, STRING_UNITS_10, "1.00 MB");
	check(test, 1000, 1000000000000000000ULL, STRING_UNITS_10, "1.00 ZB");
}

static void flags(struct kunit *test)
{
	check(test, 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "1.00kB");
	check(test, 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "1.00 k");
	check(test, 1000, 1,
	      STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
	      "1.00k");
	check(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE, "1.00KiB");
	check(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "1.00 Ki");
	check(test, 5, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "5 ");
	check(test, 5, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "5B");
}

static void large_values(struct kunit *test)
{
	check(test, U64_MAX, 1, STRING_UNITS_10, "18.4 EB");
	check(test, U64_MAX, 1, STRING_UNITS_2, "16.0 EiB");
	check(test, U32_MAX, 1, STRING_UNITS_10, "4.29 GB");
	check(test, 1ULL << 32, 1, STRING_UNITS_2, "4.00 GiB");
	check(test, 1, 1ULL << 32, STRING_UNITS_2, "4.00 GiB");
	check(test, 1ULL << 32, 1ULL << 32, STRING_UNITS_2, "16.0 EiB");
}

static void unknown_unit(struct kunit *test)
{
	char buf[32];

	string_get_size(U64_MAX, U64_MAX, STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_NOT_NULL(test, strstr(buf, "UNK"));
	string_get_size(U64_MAX, U64_MAX, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_NOT_NULL(test, strstr(buf, "UNK"));
}

static void truncation(struct kunit *test)
{
	char buf[16];
	int ret;

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.0");

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], '\0');
	KUNIT_EXPECT_EQ(test, buf[1], 'x');

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], 'x');

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 kB");

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 7);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 k");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(zero_cases),
	KUNIT_CASE(below_divisor),
	KUNIT_CASE(divisor_boundary),
	KUNIT_CASE(rounding_base10),
	KUNIT_CASE(significant_figures),
	KUNIT_CASE(base2_fractions),
	KUNIT_CASE(block_size),
	KUNIT_CASE(flags),
	KUNIT_CASE(large_values),
	KUNIT_CASE(unknown_unit),
	KUNIT_CASE(truncation),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for string_get_size");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/module.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define SENT 0xAA
#define BUFSZ 64

/* Escape src (isz bytes) into a sentinel-filled buffer and verify result. */
static void check_esc(struct kunit *test, const char *src, size_t isz,
		      unsigned int flags, const char *only, const char *exp)
{
	char buf[BUFSZ];
	size_t elen = strlen(exp);
	int ret;

	memset(buf, SENT, sizeof(buf));
	ret = string_escape_mem(src, isz, buf, sizeof(buf), flags, only);
	KUNIT_ASSERT_EQ(test, ret, (int)elen);
	KUNIT_EXPECT_MEMEQ(test, buf, exp, elen);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[elen], (unsigned char)SENT);
}

static void esc_empty_input(struct kunit *test)
{
	char buf[4];

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, buf, sizeof(buf),
						ESCAPE_ANY, NULL), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[0], (unsigned char)SENT);
}

static void esc_no_flags_passthrough(struct kunit *test)
{
	check_esc(test, "a\n\\\"\x01\xff", 6, 0, NULL, "a\n\\\"\x01\xff");
}

static void esc_space(struct kunit *test)
{
	check_esc(test, "\n\r\t\v\f", 5, ESCAPE_SPACE, NULL, "\\n\\r\\t\\v\\f");
	check_esc(test, " a", 2, ESCAPE_SPACE, NULL, " a");
	/* Not selected: specials stay raw */
	check_esc(test, "\"\\\a", 3, ESCAPE_SPACE, NULL, "\"\\\a");
}

static void esc_special(struct kunit *test)
{
	check_esc(test, "\\\a\e\"", 4, ESCAPE_SPECIAL, NULL, "\\\\\\a\\e\\\"");
	check_esc(test, "\n\t", 2, ESCAPE_SPECIAL, NULL, "\n\t");
}

static void esc_null(struct kunit *test)
{
	check_esc(test, "a\0b", 3, ESCAPE_NULL, NULL, "a\\0b");
	check_esc(test, "\x01", 1, ESCAPE_NULL, NULL, "\x01");
}

static void esc_embedded_nul_uses_isz(struct kunit *test)
{
	char buf[8];

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("a\0b", 3, buf, sizeof(buf),
						0, NULL), 3);
	KUNIT_EXPECT_MEMEQ(test, buf, "a\0b", 3);
}

static void esc_octal(struct kunit *test)
{
	check_esc(test, "\x01\xff\n \x7f", 5, ESCAPE_OCTAL, NULL,
		  "\\001\\377\\012\\040\\177");
	check_esc(test, "\0\x07\x08\x38\x40", 5, ESCAPE_OCTAL, NULL,
		  "\\000\\007\\010\\070\\100");
	check_esc(test, "\x80\xc0", 2, ESCAPE_OCTAL, NULL, "\\200\\300");
}

static void esc_hex(struct kunit *test)
{
	check_esc(test, "\x01\xab\xff\x00", 4, ESCAPE_HEX, NULL,
		  "\\x01\\xab\\xff\\x00");
	check_esc(test, "\x09\x0a\x0f\x10", 4, ESCAPE_HEX, NULL,
		  "\\x09\\x0a\\x0f\\x10");
}

static void esc_octal_beats_hex(struct kunit *test)
{
	check_esc(test, "\x01", 1, ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\001");
}

static void esc_priority_over_octal(struct kunit *test)
{
	unsigned int f = ESCAPE_SPACE | ESCAPE_SPECIAL | ESCAPE_NULL |
			 ESCAPE_OCTAL;

	check_esc(test, "\n\"\0\x01", 4, f, NULL, "\\n\\\"\\0\\001");
	check_esc(test, "\n\0", 2, ESCAPE_SPACE | ESCAPE_HEX, NULL, "\\n\\x00");
	check_esc(test, "\"\0", 2, ESCAPE_SPECIAL | ESCAPE_HEX, NULL,
		  "\\\"\\x00");
	check_esc(test, "\0", 1, ESCAPE_NULL | ESCAPE_OCTAL, NULL, "\\0");
}

static void esc_np(struct kunit *test)
{
	check_esc(test, "a \x01\x7f\x80\n", 6, ESCAPE_NP | ESCAPE_OCTAL, NULL,
		  "a \\001\\177\\200\\012");
	/* Printable chars pass even when SPECIAL would catch them */
	check_esc(test, "\"\\\a", 3, ESCAPE_NP | ESCAPE_SPECIAL, NULL,
		  "\"\\\\a");
}

static void esc_na(struct kunit *test)
{
	check_esc(test, "a\x01\x7f\x80\xa1", 5, ESCAPE_NA | ESCAPE_OCTAL, NULL,
		  "a\x01\x7f\\200\\241");
	check_esc(test, "\x7f\xff", 2, ESCAPE_NA | ESCAPE_HEX, NULL,
		  "\x7f\\xff");
}

static void esc_nap(struct kunit *test)
{
	check_esc(test, "a \x01\x7f\x80\xa1\n", 7, ESCAPE_NAP | ESCAPE_OCTAL,
		  NULL, "a \\001\\177\\200\\241\\012");
	check_esc(test, "a\n\xa1", 3, ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_HEX,
		  NULL, "a\\n\\xa1");
}

static void esc_only(struct kunit *test)
{
	/* Only '\n' is subject to escaping; tab is copied raw */
	check_esc(test, "a\n\t", 3, ESCAPE_SPACE, "\n", "a\\n\t");
	check_esc(test, "\n\t", 2, ESCAPE_SPACE, "\t", "\n\\t");
	check_esc(test, "abc", 3, ESCAPE_OCTAL, "b", "a\\142c");
	/* Class not selected: nothing is escaped */
	check_esc(test, "\n", 1, ESCAPE_SPECIAL, "\n", "\n");
}

static void esc_only_empty_ignored(struct kunit *test)
{
	check_esc(test, "a\n", 2, ESCAPE_SPACE, "", "a\\n");
	check_esc(test, "a\n", 2, ESCAPE_SPACE, NULL, "a\\n");
}

static void esc_append(struct kunit *test)
{
	unsigned int f = ESCAPE_NP | ESCAPE_OCTAL | ESCAPE_APPEND;

	check_esc(test, "abc", 3, f, "a", "\\141bc");
	check_esc(test, "abc", 3, f, "ac", "\\141b\\143");
	check_esc(test, "a\x01", 2, f, "b", "a\\001");
	check_esc(test, "a\x80", 2, ESCAPE_NA | ESCAPE_HEX | ESCAPE_APPEND,
		  "a", "\\x61\\x80");
	check_esc(test, "ab", 2, ESCAPE_NAP | ESCAPE_OCTAL | ESCAPE_APPEND,
		  "b", "a\\142");
}

static void esc_return_with_null_dst(struct kunit *test)
{
	char big[300];

	KUNIT_EXPECT_EQ(test, string_escape_mem("\n", 1, NULL, 0,
						ESCAPE_SPACE, NULL), 2);
	KUNIT_EXPECT_EQ(test, string_escape_mem("\x01\x02", 2, NULL, 0,
						ESCAPE_HEX, NULL), 8);
	KUNIT_EXPECT_EQ(test, string_escape_mem("ab", 2, NULL, 0, 0, NULL), 2);
	memset(big, 'x', sizeof(big));
	KUNIT_EXPECT_EQ(test, string_escape_mem(big, sizeof(big), NULL, 0,
						ESCAPE_OCTAL, NULL), 1200);
}

/* For every output size, verify return value, prefix and no overrun. */
static void check_trunc(struct kunit *test, const char *src, size_t isz,
			unsigned int flags, const char *only, const char *exp)
{
	size_t elen = strlen(exp), osz, i;
	char buf[BUFSZ];

	KUNIT_ASSERT_LT(test, elen + 4, (size_t)BUFSZ);
	for (osz = 0; osz <= elen + 3; osz++) {
		size_t n = osz < elen ? osz : elen;

		memset(buf, SENT, sizeof(buf));
		KUNIT_ASSERT_EQ(test, string_escape_mem(src, isz, buf, osz,
							flags, only), (int)elen);
		KUNIT_EXPECT_MEMEQ(test, buf, exp, n);
		for (i = n; i < sizeof(buf); i++)
			KUNIT_ASSERT_EQ_MSG(test, (unsigned char)buf[i],
					    (unsigned char)SENT,
					    "osz=%zu wrote at %zu", osz, i);
	}
}

static void esc_truncation_sweep(struct kunit *test)
{
	check_trunc(test, "a\n\"\0\x01", 5,
		    ESCAPE_SPACE | ESCAPE_SPECIAL | ESCAPE_NULL | ESCAPE_OCTAL,
		    NULL, "a\\n\\\"\\0\\001");
	check_trunc(test, "\x01\xab", 2, ESCAPE_HEX, NULL, "\\x01\\xab");
	check_trunc(test, "abc", 3, 0, NULL, "abc");
	check_trunc(test, "a\n\xa1", 3, ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_HEX,
		    NULL, "a\\n\\xa1");
}

static void esc_exact_fit_and_one_short(struct kunit *test)
{
	char buf[8];

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("\n", 1, buf, 2, ESCAPE_SPACE,
						NULL), 2);
	KUNIT_EXPECT_MEMEQ(test, buf, "\\n", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[2], (unsigned char)SENT);

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("\n", 1, buf, 1, ESCAPE_SPACE,
						NULL), 2);
	KUNIT_EXPECT_EQ(test, buf[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[1], (unsigned char)SENT);

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("a", 1, buf, 1, 0, NULL), 1);
	KUNIT_EXPECT_EQ(test, buf[0], 'a');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[1], (unsigned char)SENT);
}

static void esc_overflow_continues_counting(struct kunit *test)
{
	char buf[3];

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("abcdef", 6, buf, 3, 0, NULL),
			6);
	KUNIT_EXPECT_MEMEQ(test, buf, "abc", 3);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(esc_empty_input),
	KUNIT_CASE(esc_no_flags_passthrough),
	KUNIT_CASE(esc_space),
	KUNIT_CASE(esc_special),
	KUNIT_CASE(esc_null),
	KUNIT_CASE(esc_embedded_nul_uses_isz),
	KUNIT_CASE(esc_octal),
	KUNIT_CASE(esc_hex),
	KUNIT_CASE(esc_octal_beats_hex),
	KUNIT_CASE(esc_priority_over_octal),
	KUNIT_CASE(esc_np),
	KUNIT_CASE(esc_na),
	KUNIT_CASE(esc_nap),
	KUNIT_CASE(esc_only),
	KUNIT_CASE(esc_only_empty_ignored),
	KUNIT_CASE(esc_append),
	KUNIT_CASE(esc_return_with_null_dst),
	KUNIT_CASE(esc_truncation_sweep),
	KUNIT_CASE(esc_exact_fit_and_one_short),
	KUNIT_CASE(esc_overflow_continues_counting),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

