#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define BUFSZ 32

/* Run string_unescape on a copy of @in and check result, length and canary. */
static void check_unesc(struct kunit *test, const char *in, size_t size,
			unsigned int flags, const char *want, int want_ret)
{
	char src[BUFSZ], dst[BUFSZ];
	int ret;

	strscpy(src, in, sizeof(src));
	memset(dst, 0x7f, sizeof(dst));

	ret = string_unescape(src, dst, size, flags);

	KUNIT_EXPECT_EQ(test, ret, want_ret);
	KUNIT_EXPECT_EQ(test, (int)strlen(dst), want_ret);
	KUNIT_EXPECT_MEMEQ(test, dst, want, want_ret + 1);
	/* nothing written past the terminator */
	KUNIT_EXPECT_EQ(test, dst[want_ret + 1], 0x7f);
}

static void unescape_empty(struct kunit *test)
{
	check_unesc(test, "", 0, UNESCAPE_ANY, "", 0);
	check_unesc(test, "", 5, UNESCAPE_ANY, "", 0);
}

static void unescape_plain(struct kunit *test)
{
	check_unesc(test, "hello", 0, UNESCAPE_ANY, "hello", 5);
	check_unesc(test, "hello", 0, 0, "hello", 5);
}

static void unescape_no_flags(struct kunit *test)
{
	check_unesc(test, "a\\nb\\x41\\101\\\\", 0, 0,
		    "a\\nb\\x41\\101\\\\", 14);
}

static void unescape_space_all(struct kunit *test)
{
	check_unesc(test, "\\n\\r\\t\\v\\f", 0, UNESCAPE_SPACE, "\n\r\t\v\f", 5);
	check_unesc(test, "a\\nb", 0, UNESCAPE_SPACE, "a\nb", 3);
}

static void unescape_space_flag_off(struct kunit *test)
{
	check_unesc(test, "\\n", 0,
		    UNESCAPE_SPECIAL | UNESCAPE_HEX | UNESCAPE_OCTAL, "\\n", 2);
}

static void unescape_octal_digits(struct kunit *test)
{
	check_unesc(test, "\\1", 0, UNESCAPE_OCTAL, "\001", 1);
	check_unesc(test, "\\12", 0, UNESCAPE_OCTAL, "\n", 1);
	check_unesc(test, "\\101", 0, UNESCAPE_OCTAL, "A", 1);
	check_unesc(test, "\\7", 0, UNESCAPE_OCTAL, "\007", 1);
}

static void unescape_octal_limits(struct kunit *test)
{
	char src[BUFSZ] = "\\377", dst[BUFSZ];
	int ret = string_unescape(src, dst, 0, UNESCAPE_OCTAL);

	KUNIT_EXPECT_EQ(test, ret, 1);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[0], 0xff);
	KUNIT_EXPECT_EQ(test, dst[1], 0);

	/* at most three digits consumed */
	check_unesc(test, "\\1011", 0, UNESCAPE_OCTAL, "A1", 2);
	check_unesc(test, "\\0101", 0, UNESCAPE_OCTAL, "\b1", 2);
	/* non-octal digit stops the number or is not an escape */
	check_unesc(test, "\\18", 0, UNESCAPE_OCTAL, "\0018", 2);
	check_unesc(test, "\\8", 0, UNESCAPE_OCTAL, "\\8", 2);
}

static void unescape_octal_flag_off(struct kunit *test)
{
	check_unesc(test, "\\101", 0, UNESCAPE_SPACE | UNESCAPE_HEX, "\\101", 4);
}

static void unescape_hex_basic(struct kunit *test)
{
	check_unesc(test, "\\x41", 0, UNESCAPE_HEX, "A", 1);
	check_unesc(test, "\\x4", 0, UNESCAPE_HEX, "\004", 1);
	check_unesc(test, "\\x4a", 0, UNESCAPE_HEX, "J", 1);
	check_unesc(test, "\\x4A", 0, UNESCAPE_HEX, "J", 1);
	check_unesc(test, "\\x0a", 0, UNESCAPE_HEX, "\n", 1);
	check_unesc(test, "\\xaf", 0, UNESCAPE_HEX, "\xaf", 1);
}

static void unescape_hex_limits(struct kunit *test)
{
	/* at most two hex digits */
	check_unesc(test, "\\x414", 0, UNESCAPE_HEX, "A4", 2);
	/* non-hex second char stops */
	check_unesc(test, "\\x4g", 0, UNESCAPE_HEX, "\004g", 2);
	check_unesc(test, "\\xf", 0, UNESCAPE_HEX, "\017", 1);
	check_unesc(test, "\\x9z", 0, UNESCAPE_HEX, "\011z", 2);
}

static void unescape_hex_invalid(struct kunit *test)
{
	check_unesc(test, "\\xg", 0, UNESCAPE_HEX, "\\xg", 3);
	check_unesc(test, "\\x", 0, UNESCAPE_HEX, "\\x", 2);
	check_unesc(test, "\\xz1", 0, UNESCAPE_HEX, "\\xz1", 4);
}

static void unescape_hex_flag_off(struct kunit *test)
{
	check_unesc(test, "\\x41", 0, UNESCAPE_SPACE | UNESCAPE_OCTAL, "\\x41", 4);
}

static void unescape_special_all(struct kunit *test)
{
	check_unesc(test, "\\\"\\\\\\a\\e", 0, UNESCAPE_SPECIAL, "\"\\\a\e", 4);
}

static void unescape_special_flag_off(struct kunit *test)
{
	check_unesc(test, "\\\\", 0, UNESCAPE_SPACE, "\\\\", 2);
	check_unesc(test, "\\a", 0, UNESCAPE_SPACE | UNESCAPE_HEX, "\\a", 2);
}

static void unescape_unknown_escape(struct kunit *test)
{
	check_unesc(test, "\\q", 0, UNESCAPE_ANY, "\\q", 2);
	check_unesc(test, "\\ ", 0, UNESCAPE_ANY, "\\ ", 2);
	check_unesc(test, "a\\zb", 0, UNESCAPE_ANY, "a\\zb", 4);
}

static void unescape_trailing_backslash(struct kunit *test)
{
	check_unesc(test, "\\", 0, UNESCAPE_ANY, "\\", 1);
	check_unesc(test, "ab\\", 0, UNESCAPE_ANY, "ab\\", 3);
}

static void unescape_any_mixed(struct kunit *test)
{
	check_unesc(test, "\\x41\\102\\t\\\"", 0, UNESCAPE_ANY, "AB\t\"", 4);
}

static void unescape_double_backslash_then_char(struct kunit *test)
{
	/* an escaped backslash followed by 'n' is not a newline */
	check_unesc(test, "\\\\n", 0, UNESCAPE_ANY, "\\n", 2);
}

static void unescape_in_place(struct kunit *test)
{
	char buf[BUFSZ] = "a\\tb\\x41\\102";
	int ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);

	KUNIT_EXPECT_EQ(test, ret, 5);
	KUNIT_EXPECT_STREQ(test, buf, "a\tbAB");
}

static void unescape_size_truncates_plain(struct kunit *test)
{
	check_unesc(test, "abcdef", 1, UNESCAPE_ANY, "", 0);
	check_unesc(test, "abcdef", 2, UNESCAPE_ANY, "a", 1);
	check_unesc(test, "abcdef", 4, UNESCAPE_ANY, "abc", 3);
	check_unesc(test, "abcdef", 6, UNESCAPE_ANY, "abcde", 5);
	check_unesc(test, "abcdef", 7, UNESCAPE_ANY, "abcdef", 6);
	check_unesc(test, "abcdef", 8, UNESCAPE_ANY, "abcdef", 6);
}

static void unescape_size_with_escape(struct kunit *test)
{
	/* an escape is only decoded when more than one byte of budget is left */
	check_unesc(test, "\\n", 2, UNESCAPE_ANY, "\\", 1);
	check_unesc(test, "\\n", 3, UNESCAPE_ANY, "\n", 1);
	check_unesc(test, "\\n", 4, UNESCAPE_ANY, "\n", 1);
	check_unesc(test, "a\\nb", 3, UNESCAPE_ANY, "a\\", 2);
	check_unesc(test, "a\\nb", 4, UNESCAPE_ANY, "a\n", 2);
	check_unesc(test, "a\\nb", 5, UNESCAPE_ANY, "a\nb", 3);
}

static void unescape_size_one_writes_nul_only(struct kunit *test)
{
	check_unesc(test, "\\n", 1, UNESCAPE_ANY, "", 0);
	check_unesc(test, "x", 1, UNESCAPE_ANY, "", 0);
}

