static void get_option_simple(struct kunit *test)
{
	char buf[] = "42";
	char *s = buf;
	int v = 0;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 1);
	KUNIT_EXPECT_EQ(test, v, 42);
	KUNIT_EXPECT_PTR_EQ(test, s, buf + 2);
}

static void get_option_comma(struct kunit *test)
{
	char buf[] = "7,8";
	char *s = buf;
	int v = 0;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 2);
	KUNIT_EXPECT_EQ(test, v, 7);
	KUNIT_EXPECT_PTR_EQ(test, s, buf + 2);
	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 1);
	KUNIT_EXPECT_EQ(test, v, 8);
}

static void get_option_trailing_comma(struct kunit *test)
{
	char buf[] = "5,";
	char *s = buf;
	int v = 0;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 2);
	KUNIT_EXPECT_EQ(test, v, 5);
	KUNIT_EXPECT_PTR_EQ(test, s, buf + 2);
	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 0);
}

static void get_option_negative(struct kunit *test)
{
	char buf[] = "-15,3";
	char *s = buf;
	int v = 0;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 2);
	KUNIT_EXPECT_EQ(test, v, -15);
	KUNIT_EXPECT_PTR_EQ(test, s, buf + 4);
}

static void get_option_range(struct kunit *test)
{
	char buf[] = "3-9";
	char *s = buf;
	int v = 0;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 3);
	KUNIT_EXPECT_EQ(test, v, 3);
	KUNIT_EXPECT_PTR_EQ(test, s, buf + 1);
	/* the hyphen is not consumed; the next call sees a negative number */
	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 1);
	KUNIT_EXPECT_EQ(test, v, -9);
}

static void get_option_range_negative_start(struct kunit *test)
{
	char buf[] = "-3-9";
	char *s = buf;
	int v = 0;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 3);
	KUNIT_EXPECT_EQ(test, v, -3);
	KUNIT_EXPECT_PTR_EQ(test, s, buf + 2);
}

static void get_option_null_string(struct kunit *test)
{
	char *s = NULL;
	int v = 123;

	KUNIT_EXPECT_EQ(test, get_option(&s, &v), 0);
	KUNIT_EXPECT_EQ(test, v, 123);
	KUNIT_EXPECT_NULL(test, s);
}

static void get_option_empty(struct kunit *test)
{
	char buf[] = "";
	char *s = buf;
	int v = 123;

