#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>
#include <linux/module.h>

static void check_parse(struct kunit *test, const char *s,
			unsigned long long exp, size_t consumed)
{
	char *end = NULL;

	KUNIT_EXPECT_EQ(test, memparse(s, &end), exp);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s + consumed);
}

static void memparse_plain_test(struct kunit *test)
{
	check_parse(test, "0", 0, 1);
	check_parse(test, "1", 1, 1);
	check_parse(test, "123", 123, 3);
	check_parse(test, "4096", 4096, 4);
}

static void memparse_bases_test(struct kunit *test)
{
	check_parse(test, "0x10", 16, 4);
	check_parse(test, "0X1f", 31, 4);
	check_parse(test, "010", 8, 3);
	check_parse(test, "0x10K", 16ULL << 10, 5);
}

static void memparse_lower_suffix_test(struct kunit *test)
{
	check_parse(test, "1k", 1ULL << 10, 2);
	check_parse(test, "1m", 1ULL << 20, 2);
	check_parse(test, "1g", 1ULL << 30, 2);
	check_parse(test, "1t", 1ULL << 40, 2);
	check_parse(test, "1p", 1ULL << 50, 2);
	check_parse(test, "1e", 1ULL << 60, 2);
}

static void memparse_upper_suffix_test(struct kunit *test)
{
	check_parse(test, "1K", 1ULL << 10, 2);
	check_parse(test, "1M", 1ULL << 20, 2);
	check_parse(test, "1G", 1ULL << 30, 2);
	check_parse(test, "1T", 1ULL << 40, 2);
	check_parse(test, "1P", 1ULL << 50, 2);
	check_parse(test, "1E", 1ULL << 60, 2);
}

static void memparse_multiplier_test(struct kunit *test)
{
	check_parse(test, "3K", 3072, 2);
	check_parse(test, "7M", 7ULL << 20, 2);
	check_parse(test, "15E", 15ULL << 60, 3);
	check_parse(test, "0K", 0, 2);
	check_parse(test, "0E", 0, 2);
}

static void memparse_trailing_test(struct kunit *test)
{
	check_parse(test, "64K,foo", 64ULL << 10, 3);
	check_parse(test, "64@0x1000", 64, 2);
	check_parse(test, "16MB", 16ULL << 20, 3);
	check_parse(test, "5KK", 5ULL << 10, 2);
	check_parse(test, "12 K", 12, 2);
	check_parse(test, "100x", 100, 3);
}

static void memparse_invalid_test(struct kunit *test)
{
	check_parse(test, "", 0, 0);
	check_parse(test, "abc", 0, 0);
	check_parse(test, "-", 0, 0);
	/* A bare suffix parses as 0 and still consumes the suffix. */
	check_parse(test, "K", 0, 1);
	check_parse(test, "x", 0, 0);
}

static void memparse_null_retptr_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, memparse("8K", NULL), 8ULL << 10);
	KUNIT_EXPECT_EQ(test, memparse("9", NULL), 9ULL);
	KUNIT_EXPECT_EQ(test, memparse("", NULL), 0ULL);
}

static void memparse_large_test(struct kunit *test)
{
	check_parse(test, "4294967295", 0xffffffffULL, 10);
	check_parse(test, "4294967296", 0x100000000ULL, 10);
	check_parse(test, "4G", 1ULL << 32, 2);
	check_parse(test, "18446744073709551615", ULLONG_MAX, 20);
	check_parse(test, "0xffffffffffffffff", ULLONG_MAX, 18);
	check_parse(test, "7E", 7ULL << 60, 2);
}

static void memparse_overflow_test(struct kunit *test)
{
	/* 16E == 2^64, wraps to 0 */
	check_parse(test, "16E", 0, 3);
	check_parse(test, "2E", 2ULL << 60, 2);
	check_parse(test, "8E", 8ULL << 60, 2);
}

static void memparse_retptr_continue_test(struct kunit *test)
{
	const char *s = "2M 3";
	char *end = NULL;

	KUNIT_EXPECT_EQ(test, memparse(s, &end), 2ULL << 20);
	KUNIT_ASSERT_NOT_NULL(test, end);
	KUNIT_EXPECT_EQ(test, *end, ' ');
	KUNIT_EXPECT_EQ(test, memparse(end + 1, &end), 3ULL);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s + 4);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(memparse_plain_test),
	KUNIT_CASE(memparse_bases_test),
