static const siphash_key_t agt_key = {
	{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }
};

/* Independent byte-wise SipHash-2-4 reference. */
#define AGT_ROUND do { \
	v0 += v1; v1 = rol64(v1, 13); v1 ^= v0; v0 = rol64(v0, 32); \
	v2 += v3; v3 = rol64(v3, 16); v3 ^= v2; \
	v0 += v3; v3 = rol64(v3, 21); v3 ^= v0; \
	v2 += v1; v1 = rol64(v1, 17); v1 ^= v2; v2 = rol64(v2, 32); \
} while (0)

static u64 agt_ref(const u8 *p, size_t len, const siphash_key_t *k)
{
	u64 v0 = 0x736f6d6570736575ULL ^ k->key[0];
	u64 v1 = 0x646f72616e646f6dULL ^ k->key[1];
	u64 v2 = 0x6c7967656e657261ULL ^ k->key[0];
	u64 v3 = 0x7465646279746573ULL ^ k->key[1];
	u64 b = (u64)len << 56, m;
	size_t i, full = len / 8;

	for (i = 0; i < full; i++) {
		m = get_unaligned_le64(p + i * 8);
		v3 ^= m; AGT_ROUND; AGT_ROUND; v0 ^= m;
	}
	for (i = 0; i < len % 8; i++)
		b |= (u64)p[full * 8 + i] << (8 * i);
	v3 ^= b; AGT_ROUND; AGT_ROUND; v0 ^= b;
	v2 ^= 0xff;
	AGT_ROUND; AGT_ROUND; AGT_ROUND; AGT_ROUND;
	return (v0 ^ v1) ^ (v2 ^ v3);
}

static void agt_fill(u8 *buf, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		buf[i] = (u8)i;
}

static void agt_known_vectors(struct kunit *test)
{
	u8 buf[16] __aligned(8);

	agt_fill(buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 0, &agt_key),
			0x726fdb47dd0e0e31ULL);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 15, &agt_key),
			0xa129ca6149be45e5ULL);
}

static void agt_all_lengths(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8);
	size_t len;

	agt_fill(buf, sizeof(buf));
	for (len = 0; len <= AGT_MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(buf, len, &agt_key),
				    agt_ref(buf, len, &agt_key), "len=%zu", len);
}

static void agt_random_data(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8);
	size_t len, i;
	u32 s = 12345;

	for (i = 0; i < sizeof(buf); i++) {
		s = s * 1664525 + 1013904223;
		buf[i] = s >> 24;
	}
	for (len = 0; len <= AGT_MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(buf, len, &agt_key),
				    agt_ref(buf, len, &agt_key), "len=%zu", len);
}

/* Every byte, including each tail byte of the partial block, must matter. */
static void agt_byte_sensitivity(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8);
	size_t len, i;
	u64 base;

	for (len = 1; len <= 24; len++) {
		agt_fill(buf, sizeof(buf));
		base = __siphash_aligned(buf, len, &agt_key);
		for (i = 0; i < len; i++) {
			buf[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test,
					    __siphash_aligned(buf, len, &agt_key),
					    base, "len=%zu byte=%zu", len, i);
			buf[i] ^= 0x01;
		}
	}
}

/* Bytes past len must not influence the result. */
static void agt_ignores_trailing_bytes(struct kunit *test)
{
	u8 a[AGT_MAXLEN] __aligned(8);
	u8 b[AGT_MAXLEN] __aligned(8);
	size_t len;

	agt_fill(a, sizeof(a));
	memset(b, 0xa5, sizeof(b));
	for (len = 0; len < 32; len++) {
		memcpy(b, a, len);
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(a, len, &agt_key),
				    __siphash_aligned(b, len, &agt_key),
				    "len=%zu", len);
	}
}

static void agt_length_is_mixed(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8) = { 0 };
	u64 prev, cur;
	size_t len;

	/* All-zero data of differing lengths must hash differently. */
	prev = __siphash_aligned(buf, 0, &agt_key);
	for (len = 1; len <= 24; len++) {
		cur = __siphash_aligned(buf, len, &agt_key);
		KUNIT_EXPECT_NE_MSG(test, cur, prev, "len=%zu", len);
		KUNIT_EXPECT_EQ(test, cur, agt_ref(buf, len, &agt_key));
		prev = cur;
	}
}

static void agt_key_sensitivity(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8);
	siphash_key_t k0 = { { 0, 0 } };
	siphash_key_t k1 = { { 1, 0 } };
	siphash_key_t k2 = { { 0, 1 } };
	siphash_key_t kf = { { ~0ULL, ~0ULL } };
	size_t len;

	agt_fill(buf, sizeof(buf));
	for (len = 0; len <= 17; len++) {
		KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, len, &k0),
				agt_ref(buf, len, &k0));
		KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, len, &kf),
				agt_ref(buf, len, &kf));
		KUNIT_EXPECT_NE(test, __siphash_aligned(buf, len, &k0),
				__siphash_aligned(buf, len, &k1));
		KUNIT_EXPECT_NE(test, __siphash_aligned(buf, len, &k0),
				__siphash_aligned(buf, len, &k2));
		KUNIT_EXPECT_NE(test, __siphash_aligned(buf, len, &k1),
				__siphash_aligned(buf, len, &k2));
	}
}

static void agt_deterministic(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8);

	agt_fill(buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 33, &agt_key),
			__siphash_aligned(buf, 33, &agt_key));
}

/* A copy at a different 8-aligned offset must hash identically. */
static void agt_aligned_offsets(struct kunit *test)
{
	u8 big[AGT_MAXLEN + 32] __aligned(8);
	u8 buf[AGT_MAXLEN] __aligned(8);
	size_t len, off;

	agt_fill(buf, sizeof(buf));
	for (off = 0; off <= 32; off += 8) {
		memcpy(big + off, buf, sizeof(buf));
		for (len = 0; len <= 40; len++)
			KUNIT_EXPECT_EQ_MSG(test,
				__siphash_aligned(big + off, len, &agt_key),
				agt_ref(buf, len, &agt_key),
				"off=%zu len=%zu", off, len);
	}
}

static void agt_high_bytes(struct kunit *test)
{
	u8 buf[AGT_MAXLEN] __aligned(8);
	size_t len;

	memset(buf, 0xff, sizeof(buf));
	for (len = 0; len <= AGT_MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(buf, len, &agt_key),
				    agt_ref(buf, len, &agt_key), "len=%zu", len);
}

#else /* CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS: symbol not built */

static void agt_unavailable(struct kunit *test)
{
	kunit_skip(test, "__siphash_aligned not built with efficient unaligned access");
}

#endif

