/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/string.h>
#include <linux/bitops.h>
#include <linux/unaligned.h>

/*
 * __hsiphash_aligned() is only built without
 * CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS; otherwise the unaligned variant is
 * the same algorithm and is tested instead.
 */
#ifdef CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS
#define HASH(d, l, k) __hsiphash_unaligned(d, l, k)
#else
#define HASH(d, l, k) __hsiphash_aligned(d, l, k)
#endif

#define BUFSZ 80

#if BITS_PER_LONG == 64
static const hsiphash_key_t agent_key = {{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }};
/* Known answers for input {0,1,...,len-1}. */
static const struct { size_t len; u32 val; } agent_kat[] = {
	{ 0, 0x050fc4dcU }, { 1, 0x7d57ca93U }, { 2, 0x4dc7d44dU },
	{ 3, 0xe7ddf7fbU }, { 4, 0x88d38328U }, { 7, 0x9bb11140U },
	{ 8, 0x8d299a8eU }, { 9, 0x6c063de4U }, { 15, 0x2a519956U },
	{ 16, 0x7d908b66U }, { 63, 0xb7bbb3a8U },
};

/* Independent reference implementation (byte-wise loads, SipHash-1-3). */
static u32 ref_hash(const u8 *p, size_t len, const hsiphash_key_t *key)
{
	u64 v0 = SIPHASH_CONST_0, v1 = SIPHASH_CONST_1;
	u64 v2 = SIPHASH_CONST_2, v3 = SIPHASH_CONST_3;
	u64 b = ((u64)len) << 56, m;
	size_t i, j, full = len / 8;

	v3 ^= key->key[1]; v2 ^= key->key[0];
	v1 ^= key->key[1]; v0 ^= key->key[0];
	for (i = 0; i < full; i++) {
		m = 0;
		for (j = 0; j < 8; j++)
			m |= (u64)p[i * 8 + j] << (8 * j);
		v3 ^= m;
		SIPHASH_PERMUTATION(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (j = 0; j < len % 8; j++)
		b |= (u64)p[full * 8 + j] << (8 * j);
	v3 ^= b;
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	return (u32)((v0 ^ v1) ^ (v2 ^ v3));
}
#else
static const hsiphash_key_t agent_key = {{ 0x03020100U, 0x07060504U }};
static const struct { size_t len; u32 val; } agent_kat[] = {
	{ 0, 0x5814c896U }, { 1, 0xe7e864caU }, { 2, 0xbc4b0e30U },
	{ 3, 0x01539939U }, { 4, 0x7e059ea6U }, { 5, 0x88e3d89bU },
	{ 7, 0x9d38d9d6U }, { 8, 0x577999b1U }, { 9, 0xc839caedU },
	{ 15, 0xd0257b04U }, { 63, 0x87178304U },
};

static u32 ref_hash(const u8 *p, size_t len, const hsiphash_key_t *key)
{
	u32 v0 = HSIPHASH_CONST_0, v1 = HSIPHASH_CONST_1;
	u32 v2 = HSIPHASH_CONST_2, v3 = HSIPHASH_CONST_3;
	u32 b = ((u32)len) << 24, m;
	size_t i, j, full = len / 4;

	v3 ^= key->key[1]; v2 ^= key->key[0];
	v1 ^= key->key[1]; v0 ^= key->key[0];
	for (i = 0; i < full; i++) {
		m = 0;
		for (j = 0; j < 4; j++)
			m |= (u32)p[i * 4 + j] << (8 * j);
		v3 ^= m;
		HSIPHASH_PERMUTATION(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (j = 0; j < len % 4; j++)
		b |= (u32)p[full * 4 + j] << (8 * j);
	v3 ^= b;
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	return v1 ^ v3;
}
#endif

static void fill_seq(u8 *p, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		p[i] = i;
}

static void agent_kat_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t i;

	fill_seq(in, sizeof(in));
	for (i = 0; i < ARRAY_SIZE(agent_kat); i++)
		KUNIT_EXPECT_EQ_MSG(test, HASH(in, agent_kat[i].len, &agent_key),
				    agent_kat[i].val, "len %zu", agent_kat[i].len);
}

static void agent_reference_all_lengths_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t len;

	fill_seq(in, sizeof(in));
	for (len = 0; len <= 64; len++)
		KUNIT_EXPECT_EQ_MSG(test, HASH(in, len, &agent_key),
				    ref_hash(in, len, &agent_key), "len %zu", len);
}

static void agent_reference_random_data_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	hsiphash_key_t key;
	size_t len, i;
	u32 seed = 12345;

	for (len = 0; len <= 40; len++) {
		for (i = 0; i < sizeof(in); i++) {
			seed = seed * 1664525 + 1013904223;
			in[i] = seed >> 24;
		}
		for (i = 0; i < ARRAY_SIZE(key.key); i++) {
			seed = seed * 1664525 + 1013904223;
			key.key[i] = (unsigned long)seed * 2654435761UL + seed;
		}
		KUNIT_EXPECT_EQ_MSG(test, HASH(in, len, &key),
				    ref_hash(in, len, &key), "len %zu", len);
	}
}

static void agent_high_bytes_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t len;

	memset(in, 0xff, sizeof(in));
	for (len = 0; len <= 40; len++)
		KUNIT_EXPECT_EQ_MSG(test, HASH(in, len, &agent_key),
				    ref_hash(in, len, &agent_key), "len %zu", len);
}

static void agent_empty_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);

	memset(in, 0xa5, sizeof(in));
	KUNIT_EXPECT_EQ(test, HASH(in, 0, &agent_key), ref_hash(in, 0, &agent_key));
	/* Contents are irrelevant for an empty input. */
	memset(in, 0, sizeof(in));
	KUNIT_EXPECT_EQ(test, HASH(in, 0, &agent_key), ref_hash(in, 0, &agent_key));
}

static void agent_bytes_beyond_len_ignored_test(struct kunit *test)
{
	u8 a[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	u8 b[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t len;

	fill_seq(a, sizeof(a));
	for (len = 0; len <= 40; len++) {
		memcpy(b, a, sizeof(b));
		memset(b + len, 0xee, sizeof(b) - len);
		KUNIT_EXPECT_EQ_MSG(test, HASH(a, len, &agent_key),
				    HASH(b, len, &agent_key), "len %zu", len);
	}
}

static void agent_every_byte_matters_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t len, i;
	u32 base;

	for (len = 1; len <= 40; len++) {
		fill_seq(in, sizeof(in));
		base = HASH(in, len, &agent_key);
		for (i = 0; i < len; i++) {
			in[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test, HASH(in, len, &agent_key), base,
					    "len %zu byte %zu", len, i);
			in[i] ^= 0x01;
		}
		KUNIT_EXPECT_EQ(test, HASH(in, len, &agent_key), base);
	}
}

static void agent_length_matters_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t a, b;

	memset(in, 0, sizeof(in));
	for (a = 0; a <= 24; a++)
		for (b = a + 1; b <= 24; b++)
			KUNIT_EXPECT_NE_MSG(test, HASH(in, a, &agent_key),
					    HASH(in, b, &agent_key),
					    "lens %zu %zu", a, b);
}

static void agent_key_matters_test(struct kunit *test)
{
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	hsiphash_key_t k;
	size_t len, w;

	fill_seq(in, sizeof(in));
	for (len = 0; len <= 20; len++) {
		u32 base = HASH(in, len, &agent_key);

		for (w = 0; w < ARRAY_SIZE(k.key); w++) {
			k = agent_key;
			k.key[w] ^= 1;
			KUNIT_EXPECT_NE_MSG(test, HASH(in, len, &k), base,
					    "len %zu key word %zu", len, w);
			KUNIT_EXPECT_EQ(test, HASH(in, len, &k), ref_hash(in, len, &k));
		}
	}
}

static void agent_aligned_offset_test(struct kunit *test)
{
	u8 buf[BUFSZ + 2 * SIPHASH_ALIGNMENT] __aligned(SIPHASH_ALIGNMENT);
	u8 in[BUFSZ] __aligned(SIPHASH_ALIGNMENT);
	size_t len, off;

	fill_seq(in, sizeof(in));
	for (off = 0; off <= 2 * SIPHASH_ALIGNMENT; off += SIPHASH_ALIGNMENT) {
		memset(buf, 0x5a, sizeof(buf));
		memcpy(buf + off, in, sizeof(in));
		for (len = 0; len <= 40; len++)
			KUNIT_EXPECT_EQ_MSG(test, HASH(buf + off, len, &agent_key),
					    HASH(in, len, &agent_key),
					    "off %zu len %zu", off, len);
	}
}

static void agent_input_unmodified_test(struct kunit *test)
