	u8 copy[BUFSZ];
	hsiphash_key_t k = agent_key;

	fill_seq(in, sizeof(in));
	memcpy(copy, in, sizeof(in));
	HASH(in, 37, &k);
	KUNIT_EXPECT_EQ(test, memcmp(in, copy, sizeof(in)), 0);
	KUNIT_EXPECT_EQ(test, memcmp(&k, &agent_key, sizeof(k)), 0);
