static void agent_fixed_helpers_test(struct kunit *test)
{
	u8 in[16] __aligned(SIPHASH_ALIGNMENT);
	u32 w[4];
	size_t i;

	fill_seq(in, sizeof(in));
	for (i = 0; i < 4; i++)
		w[i] = get_unaligned_le32(in + 4 * i);
	KUNIT_EXPECT_EQ(test, HASH(in, 4, &agent_key), hsiphash_1u32(w[0], &agent_key));
